-- ============================================================================
-- CCIS Students Masterlist Table & Orientation Roster Seed (1,817 Students)
-- Designated by Program:
--   BSIT -> Society of Information Technology Students (925)
--   BSIS -> Information System Students (483)
--   BSCS -> Computer Science Students (409)
-- ============================================================================

DO $$ BEGIN
  CREATE TYPE public."Program" AS ENUM ('BSCS', 'BSIS', 'BSIT');
EXCEPTION
  WHEN duplicate_object THEN NULL;
END $$;

CREATE TABLE IF NOT EXISTS public.students (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  student_no text NOT NULL,
  full_name text NOT NULL,
  program public."Program" NOT NULL,
  year_level text NOT NULL,
  organization_id uuid NOT NULL,
  college_id uuid NOT NULL DEFAULT '11111111-1111-4111-8111-111111111111',
  user_id uuid,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT students_pkey PRIMARY KEY (id),
  CONSTRAINT students_student_no_key UNIQUE (student_no),
  CONSTRAINT students_organization_id_fkey FOREIGN KEY (organization_id) REFERENCES public.organizations(id) ON DELETE RESTRICT,
  CONSTRAINT students_college_id_fkey FOREIGN KEY (college_id) REFERENCES public.colleges(id) ON DELETE RESTRICT,
  CONSTRAINT students_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS students_program_idx ON public.students (program);
CREATE INDEX IF NOT EXISTS students_year_level_idx ON public.students (year_level);
CREATE INDEX IF NOT EXISTS students_organization_id_idx ON public.students (organization_id);
CREATE INDEX IF NOT EXISTS students_college_id_idx ON public.students (college_id);
CREATE INDEX IF NOT EXISTS students_user_id_idx ON public.students (user_id);

ALTER TABLE public.students ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Authenticated users read students" ON public.students;
DROP POLICY IF EXISTS "Officers and admins read all students" ON public.students;
CREATE POLICY "Officers and admins read all students"
  ON public.students FOR SELECT TO authenticated
  USING (
    (SELECT auth.uid()) = user_id
    OR EXISTS (
      SELECT 1 FROM public.users u
      WHERE u.id = (SELECT auth.uid()) AND u.role <> 'STUDENT'::public."Role"
    )
  );

